	static itemIcon(id,size,dark,sub) {
		let key = id + ":" + size + ":" + sub;
		let url = menu_Menu.iconCache.h[key];
		if(url == null) {
			let dpr = window.devicePixelRatio;
			let px = size * dpr | 0;
			let c = menu_Menu.doc.createElement("canvas");
			c.width = c.height = px;
			let mc = menu_Menu.root.attachMovie(id >= 1000 ? "hammer_item_score" : "hammer_item_special","ic" + menu_Menu.uniq,menu_Menu.uniq++);
			if(mc != null) {
				mc.gotoAndStop(Std.string(id >= 1000 ? id - 1000 + 1 : id + 1));
				let inner = mc.sub;
				if(sub != null && inner != null) {
					inner.gotoAndStop(sub == null ? "null" : "" + sub);
				}
				let b = mc.getBounds(mc);
				let w = b.xMax - b.xMin;
				let h = b.yMax - b.yMin;
				if(w > 0 && h > 0) {
					let s = Math.min(px * 0.9 / Math.max(w,h),2.5 * dpr);
					mc.set__xscale(mc.set__yscale(s * 100));
					swf_Renderer.drawInto(c,mc,(px - w * s) / 2 - b.xMin * s,(px - h * s) / 2 - b.yMin * s);
				}
				mc.removeMovieClip();
			}
			url = c.toDataURL();
			menu_Menu.iconCache.h[key] = url;
		}
		let img = menu_Menu.doc.createElement("img");
		img.src = url;
		img.width = img.height = size;
		img.className = "item" + (dark ? " dark" : "");
		img.title = menu_Menu.itemNames.h.hasOwnProperty(id) ? menu_Menu.itemNames.h[id] : "Objet " + id;
		return img;
	}
